const cls = (...names: (string | false | undefined)[]) => names.filter(Boolean).join(" ");

function Button({ children, variant = "secondary", onClick, type = "button", className = "" }: { children: ReactNode; variant?: "primary" | "secondary" | "danger" | "ghost"; onClick?: () => void; type?: "button" | "submit"; className?: string }) {
  return <button type={type} onClick={onClick} className={cls("inline-flex h-9 items-center justify-center gap-2 rounded-md px-3.5 text-sm font-medium transition-colors", variant === "primary" && "bg-primary text-primary-foreground hover:bg-primary/90", variant === "secondary" && "border border-border bg-panel text-foreground hover:bg-accent", variant === "danger" && "border border-danger/30 bg-danger/10 text-danger hover:bg-danger/15", variant === "ghost" && "text-muted-foreground hover:bg-accent hover:text-foreground", className)}>{children}</button>;
}

function Badge({ children, tone = "muted" }: { children: ReactNode; tone?: "danger" | "success" | "info" | "warning" | "muted" }) {
  return <span className={cls("inline-flex items-center rounded-full border px-2 py-1 text-xs font-medium", tone === "danger" && "border-danger/25 bg-danger/10 text-danger", tone === "success" && "border-success/25 bg-success/10 text-success", tone === "info" && "border-info/25 bg-info/10 text-info", tone === "warning" && "border-warning/25 bg-warning/10 text-warning", tone === "muted" && "border-border bg-muted text-muted-foreground")}>{children}</span>;
}

function toneFor(status: string): "danger" | "success" | "info" | "warning" | "muted" {
  if (["Overdue", "Expired", "Received"].includes(status)) return "danger";
  if (["Paid", "Filed", "Completed", "accepted"].includes(status)) return "success";
  if (["Invoiced", "In Progress"].includes(status)) return "info";
  if (["Short", "New", "requested"].includes(status)) return "warning";
  return "muted";
}

function PageTitle({ title, subtitle, action }: { title: string; subtitle: string; action?: ReactNode }) {
  return <div className="mb-7 flex items-end justify-between gap-4"><div><h1 className="font-serif text-4xl tracking-tight text-foreground">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{subtitle}</p></div>{action}</div>;
}

function Card({ children, className = "" }: { children: ReactNode; className?: string }) {
  return <section className={cls("border border-border bg-panel", className)}>{children}</section>;
}

function Field({ label, children, helper, required = false }: { label: string; children: ReactNode; helper?: string; required?: boolean }) {
  return <label className="grid gap-2 text-sm"><span className="font-medium text-foreground">{label}{required && <span className="ml-1 text-danger">*</span>}</span>{children}{helper && <span className="text-xs leading-5 text-muted-foreground">{helper}</span>}</label>;
}

function TextInput({ placeholder, type = "text", value, onChange, required = false }: { placeholder?: string; type?: string; value?: string; onChange?: (value: string) => void; required?: boolean }) {
  return <input required={required} type={type} value={value} onChange={(e) => onChange?.(e.target.value)} placeholder={placeholder} className="h-10 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground outline-none placeholder:text-muted-foreground focus:border-ring focus:ring-1 focus:ring-ring" />;
}

function SelectInput({ value, onChange, children }: { value?: string; onChange?: (value: string) => void; children: ReactNode }) {
  return <select value={value} onChange={(e) => onChange?.(e.target.value)} className="h-10 w-full rounded-md border border-border bg-background px-3 text-sm text-foreground outline-none focus:border-ring focus:ring-1 focus:ring-ring">{children}</select>;
}

function TextArea({ placeholder, value, onChange }: { placeholder?: string; value?: string; onChange?: (value: string) => void }) {
  return <textarea value={value} onChange={(e) => onChange?.(e.target.value)} placeholder={placeholder} rows={3} className="w-full resize-y rounded-md border border-border bg-background px-3 py-2.5 text-sm text-foreground outline-none placeholder:text-muted-foreground focus:border-ring focus:ring-1 focus:ring-ring" />;
}

function Modal({ title, description, onClose, children, wide = false }: { title: string; description?: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-overlay p-4"><div className={cls("max-h-[92vh] w-full overflow-y-auto rounded-lg border border-border bg-panel shadow-modal", wide ? "max-w-3xl" : "max-w-xl")}><div className="sticky top-0 z-10 flex items-start justify-between border-b border-border bg-panel px-6 py-5"><div><h2 className="font-serif text-2xl text-foreground">{title}</h2>{description && <p className="mt-1 text-sm text-muted-foreground">{description}</p>}</div><button onClick={onClose} aria-label="Close" className="grid h-8 w-8 place-items-center rounded-md text-lg text-muted-foreground hover:bg-accent hover:text-foreground">×</button></div><div className="p-6">{children}</div></div></div>;
}

function EmptyState({ symbol = "□", title, children, action }: { symbol?: string; title: string; children: ReactNode; action?: ReactNode }) {
  return <div className="grid min-h-56 place-items-center border border-dashed border-border px-6 text-center"><div><div className="mx-auto mb-4 text-3xl text-muted-foreground">{symbol}</div><h3 className="font-serif text-xl text-foreground">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{children}</p>{action && <div className="mt-5">{action}</div>}</div></div>;
}

function StatCard({ label, value, detail, tone }: { label: string; value: string; detail?: string; tone?: "danger" | "success" | "info" }) {
  return <Card className="p-5"><p className="text-xs font-medium uppercase tracking-[0.12em] text-muted-foreground">{label}</p><p className={cls("mt-3 font-serif text-3xl", tone === "danger" && "text-danger", tone === "success" && "text-success", tone === "info" && "text-info", !tone && "text-foreground")}>{value}</p>{detail && <p className="mt-2 text-xs text-muted-foreground">{detail}</p>}</Card>;
}

function Dashboard({ deadlines, onUpdateDeadline, onOpen }: { deadlines: Deadline[]; onUpdateDeadline: (id: number) => void; onOpen: (name: ModalName) => void }) {
  return <><PageTitle title="Good morning, Sthambhalliance" subtitle="What needs your attention today." action={<div className="flex flex-wrap justify-end gap-2"><Button variant="primary" onClick={() => onOpen("client")}>＋ Add client</Button><Button onClick={() => onOpen("documents")}>＋ Request docs</Button><Button onClick={() => onOpen("fee")}>＋ Log fee</Button><Button onClick={() => onOpen("notice")}>Draft a notice reply</Button></div>} /><div className="grid gap-3 lg:grid-cols-2"><div className="border border-warning/25 bg-warning/10 p-4 text-sm text-warning"><span className="mr-2">!</span>1 new demand raised this week · <strong>₹13,17,699.50</strong> outstanding across 10 clients</div><div className="border border-warning/25 bg-warning/10 p-4 text-sm text-warning"><span className="mr-2">!</span>1 client short on advance tax · <strong>₹5,52,500</strong> in interest exposure so far</div></div><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Overdue filings" value="24" tone="danger" detail="Past the due date" /><StatCard label="Due in 7 days" value="14" tone="info" /><StatCard label="Clients" value="22" /><StatCard label="Fees overdue" value="₹12,000" tone="danger" /></div><div className="mt-8"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-serif text-2xl text-foreground">Needs attention</h2><p className="mt-1 text-sm text-muted-foreground">Overdue · 24 · Past the due date — deal with these first</p></div><Button variant="ghost">View all deadlines →</Button></div><DeadlineTable deadlines={deadlines.slice(0, 6)} onUpdate={onUpdateDeadline} /></div></>;
}

function DeadlineTable({ deadlines, onUpdate }: { deadlines: Deadline[]; onUpdate: (id: number) => void }) {
  return <Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="border-b border-border bg-muted/40 text-xs uppercase tracking-[0.1em] text-muted-foreground"><tr><th className="px-5 py-3 font-medium">Filing / service</th><th className="px-5 py-3 font-medium">Client</th><th className="px-5 py-3 font-medium">Due date</th><th className="px-5 py-3 font-medium">Status</th><th className="px-5 py-3 font-medium text-right">Action</th></tr></thead><tbody className="divide-y divide-border">{deadlines.map((row) => <tr key={row.id} className="hover:bg-accent/40"><td className="px-5 py-4"><p className="font-medium text-foreground">{row.service} <span className="font-normal text-muted-foreground">— {row.period}</span></p><p className="mt-1 text-xs text-danger">{row.days} days overdue</p></td><td className="px-5 py-4 text-muted-foreground">{row.client}</td><td className="px-5 py-4 text-muted-foreground">{row.due}</td><td className="px-5 py-4"><Badge tone={toneFor(row.status)}>{row.status}</Badge></td><td className="px-5 py-4 text-right"><div className="flex justify-end gap-2"><Button variant={row.status === "In Progress" ? "primary" : "secondary"} onClick={() => onUpdate(row.id)}>{row.status === "In Progress" ? "Mark filed" : row.status === "Filed" ? "Filed" : "Start"}</Button><Button variant="ghost" aria-label="More actions">•••</Button></div></td></tr>)}</tbody></table></div></Card>;
}

function ClientsPage({ clients, onOpen }: { clients: Client[]; onOpen: (name: ModalName) => void }) {
  const [search, setSearch] = useState(""); const [service, setService] = useState("All services");
  const filtered = clients.filter((c) => `${c.name} ${c.pan} ${c.gstin ?? ""}`.toLowerCase().includes(search.toLowerCase()) && (service === "All services" || c.services.some((s) => s.includes(service))));
  return <><PageTitle title="Clients" subtitle={`${clients.length + 7} clients`} action={<Button variant="primary" onClick={() => onOpen("client")}>＋ Add client</Button>} /><div className="mb-4 grid gap-3 sm:grid-cols-[minmax(0,1fr)_180px]"><TextInput placeholder="Search by name, PAN or GSTIN" value={search} onChange={setSearch} /><SelectInput value={service} onChange={setService}><option>All services</option><option>ITR</option><option>GSTR-1</option><option>GSTR-3B</option><option>TDS</option><option>ROC</option></SelectInput></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[750px] text-left text-sm"><thead className="border-b border-border bg-muted/40 text-xs uppercase tracking-[0.1em] text-muted-foreground"><tr><th className="px-5 py-3">Name</th><th className="px-5 py-3">Type</th><th className="px-5 py-3">PAN</th><th className="px-5 py-3">Services</th><th className="px-5 py-3"></th></tr></thead><tbody className="divide-y divide-border">{filtered.map((client) => <tr key={client.id} className="hover:bg-accent/40"><td className="px-5 py-4 font-medium text-foreground">{client.name}</td><td className="px-5 py-4 text-muted-foreground">{client.type}</td><td className="px-5 py-4 font-mono text-xs text-muted-foreground">{client.pan}</td><td className="px-5 py-4 text-muted-foreground">{client.services.join(", ")}</td><td className="px-5 py-4 text-right"><Button variant="ghost">•••</Button></td></tr>)}</tbody></table>{filtered.length === 0 && <p className="p-8 text-center text-sm text-muted-foreground">No clients match this search.</p>}</div></Card></>;
}

function DeadlinesPage({ deadlines, clients, onOpen, onUpdate }: { deadlines: Deadline[]; clients: Client[]; onOpen: (name: ModalName) => void; onUpdate: (id: number) => void }) {
  const [client, setClient] = useState("All clients"); const [service, setService] = useState("All services"); const [showFiled, setShowFiled] = useState(false);
  const filtered = deadlines.filter((d) => (client === "All clients" || d.client === client) && (service === "All services" || d.service.includes(service)) && (showFiled || d.status !== "Filed"));
  return <><PageTitle title="Deadlines" subtitle="24 overdue · 88 open" action={<Button variant="primary" onClick={() => onOpen("deadline")}>＋ Add deadline</Button>} /><div className="mb-6 flex flex-wrap items-center gap-3"><SelectInput value={client} onChange={setClient}><option>All clients</option>{clients.map((c) => <option key={c.id}>{c.name}</option>)}</SelectInput><SelectInput value={service} onChange={setService}><option>All services</option><option>GSTR-1</option><option>GSTR-3B</option><option>ITR</option><option>TDS</option></SelectInput><label className="flex h-10 items-center gap-2 rounded-md border border-border px-3 text-sm text-muted-foreground"><input type="checkbox" checked={showFiled} onChange={(e) => setShowFiled(e.target.checked)} className="accent-primary" /> Show filed</label></div><div className="mb-3"><h2 className="font-serif text-2xl text-foreground">Overdue · 24</h2><p className="mt-1 text-sm text-muted-foreground">Past the due date — deal with these first</p></div><DeadlineTable deadlines={filtered} onUpdate={onUpdate} /></>;
}

