  return <><PageTitle title="Documents" subtitle="4 links awaiting upload" action={<Button variant="primary" onClick={() => onOpen("documents")}>＋ Request documents</Button>} /><div className="mb-4 flex gap-1 border-b border-border"><Button variant="ghost" className="border-b-2 border-primary rounded-none">Requests (6)</Button><Button variant="ghost">Files (1)</Button></div><Card className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left text-sm"><thead className="border-b border-border bg-muted/40 text-xs uppercase tracking-[0.1em] text-muted-foreground"><tr><th className="px-5 py-3">Request</th><th className="px-5 py-3">Client</th><th className="px-5 py-3">Received</th><th className="px-5 py-3">Expires</th><th className="px-5 py-3">Status</th><th className="px-5 py-3"></th></tr></thead><tbody className="divide-y divide-border">{requests.map((row, i) => <tr key={`${row[0]}-${i}`} className="hover:bg-accent/40">{row.map((cell, j) => <td key={j} className="px-5 py-4 text-muted-foreground">{j === 0 ? <span className="font-medium text-foreground">{cell}</span> : j === 4 ? <Badge tone={toneFor(cell)}>{cell}</Badge> : cell}</td>)}<td className="px-5 py-4 text-right"><Button variant="ghost">Share</Button><Button variant="ghost">×</Button></td></tr>)}</tbody></table></div></Card></>;
